#include <Servo.h>

Servo servo;

void setup() {
  servo.attach(9);

  // Исходное положение
  servo.write(90);
  delay(1000);
}

void loop() {
  // Плавно влево на 90 градусов
  for (int angle = 90; angle >= 0; angle--) {
    servo.write(angle);
    delay(30);
  }

  // Стоим 2 секунды
  delay(2000);

  // Плавно возвращаемся назад
  for (int angle = 0; angle <= 90; angle++) {
    servo.write(angle);
    delay(30);
  }

  // Остановиться на исходной позиции
  delay(3000);
}
